import{_ as i,o as a,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const m=JSON.parse('{"title":"商店系统专题导航","description":"","frontmatter":{},"headers":[],"relativePath":"项目设计/商店系统专题导航.md","filePath":"项目设计/商店系统专题导航.md","lastUpdated":1777893104000}'),o={name:"项目设计/商店系统专题导航.md"};function r(c,l,h,t,n,s){return a(),e("div",null,[...l[0]||(l[0]=[d('<h1 id="商店系统专题导航" tabindex="-1">商店系统专题导航 <a class="header-anchor" href="#商店系统专题导航" aria-label="Permalink to “商店系统专题导航”">​</a></h1><p>一句话摘要：这是一份面向“要做可维护商店系统”的专题入口，重点关注商品数据、货币扣减、购买校验、库存刷新与 UI 展示之间的结构关系。</p><ul><li>适合对象：正在做背包、货币、商店、抽奖或兑换系统的制作者</li><li>当前状态：已整理</li><li>可信度：<code>[高可信推断]</code></li><li>关联文档：<code>docs/脚本系统/专题研究/创游世界背包与货币系统设计入门.md</code>、<code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code>、<code>docs/项目设计/系统设计专题导航.md</code></li></ul><h2 id="这页适合解决什么问题" tabindex="-1">这页适合解决什么问题 <a class="header-anchor" href="#这页适合解决什么问题" aria-label="Permalink to “这页适合解决什么问题”">​</a></h2><p>如果你正在遇到下面这些问题，可以先从这里进入：</p><ul><li>商品价格到底放哪一层</li><li>购买后 UI 为什么没更新</li><li>金币扣了但背包没进货</li><li>限购、刷新、折扣这些逻辑应该怎么拆</li><li>商店页和背包页是不是要共用一套数据结构</li></ul><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to “推荐阅读顺序”">​</a></h2><ol><li><code>docs/脚本系统/专题研究/创游世界背包与货币系统设计入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li></ol><h2 id="商店系统最重要的结构观念" tabindex="-1">商店系统最重要的结构观念 <a class="header-anchor" href="#商店系统最重要的结构观念" aria-label="Permalink to “商店系统最重要的结构观念”">​</a></h2><ul><li><code>[已确认]</code> 商品显示信息和商品真实数据应尽量分开。</li><li><code>[已确认]</code> 价格、库存、限购次数等不应只存在于 UI 层。</li><li><code>[已确认]</code> 购买行为至少要经过：校验条件 → 扣资源 → 发放物品 → 刷新展示。</li><li><code>[高可信推断]</code> 商店和背包最好围绕同一套“物品定义 + 玩家持有数据”展开，否则后续扩展会越来越乱。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to “常见误区”">​</a></h2><ul><li>误区 1：把商品列表直接写死在页面脚本里。 <ul><li>后果：后面一旦有刷新规则、活动商品、折扣逻辑，就很难维护。</li></ul></li><li>误区 2：先更新 UI，再做购买校验。 <ul><li>后果：容易出现显示成功、实际失败的假同步。</li></ul></li><li>误区 3：金币、钻石、券、兑换材料各自独立乱写。 <ul><li>后果：资源扣减规则分散，后期非常难统一。</li></ul></li></ul><h2 id="推荐的最小拆分" tabindex="-1">推荐的最小拆分 <a class="header-anchor" href="#推荐的最小拆分" aria-label="Permalink to “推荐的最小拆分”">​</a></h2><h3 id="商品定义层" tabindex="-1">商品定义层 <a class="header-anchor" href="#商品定义层" aria-label="Permalink to “商品定义层”">​</a></h3><p>负责：</p><ul><li>商品 ID</li><li>名称与描述</li><li>价格类型与价格数值</li><li>购买产出</li><li>限购规则</li></ul><h3 id="玩家状态层" tabindex="-1">玩家状态层 <a class="header-anchor" href="#玩家状态层" aria-label="Permalink to “玩家状态层”">​</a></h3><p>负责：</p><ul><li>当前金币 / 钻石 / 兑换材料</li><li>已购买次数</li><li>今日限购 / 周限购状态</li></ul><h3 id="交易处理层" tabindex="-1">交易处理层 <a class="header-anchor" href="#交易处理层" aria-label="Permalink to “交易处理层”">​</a></h3><p>负责：</p><ul><li>是否允许购买</li><li>扣资源</li><li>发奖励</li><li>写入购买记录</li></ul><h3 id="ui-展示层" tabindex="-1">UI 展示层 <a class="header-anchor" href="#ui-展示层" aria-label="Permalink to “UI 展示层”">​</a></h3><p>负责：</p><ul><li>显示商品列表</li><li>显示价格与是否可购买</li><li>触发购买请求</li><li>接收购买结果并刷新</li></ul><h2 id="当前仍建议继续补强的部分" tabindex="-1">当前仍建议继续补强的部分 <a class="header-anchor" href="#当前仍建议继续补强的部分" aria-label="Permalink to “当前仍建议继续补强的部分”">​</a></h2><ul><li>限购与刷新机制专题</li><li>折扣 / 活动商店专题</li><li>抽奖、兑换、礼包与普通商店的统一抽象</li><li>商店页与背包页的双向回链</li></ul><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to “关联阅读”">​</a></h2><ul><li><code>docs/项目设计/项目设计导航.md</code></li><li><code>docs/项目设计/系统设计专题导航.md</code></li><li><code>docs/核心研究/数据、变量与作用域导航.md</code></li></ul>',29)])])}const _=i(o,[["render",r]]);export{m as __pageData,_ as default};
